FUNCTION_BLOCK FB_Pharma_HotMeltExtrusion
VAR_INPUT
    bEnable                 : BOOL;     (* Master process enable command [TRUE = Run, FALSE = Idle] *)
    bEmergencyStop          : BOOL;     (* Safety interlock relay OK status [TRUE = Healthy/Closed, FALSE = Tripped] *)
    bPurgeRequest           : BOOL;     (* Operator manual command to trigger polymer flush/purge sequence *)
    bAutoTuneMpc            : BOOL;     (* Enable online model parameter adaptation for state-space controller *)
    rMeltPressure_CH1       : REAL;     (* Die head melt pressure transducer Channel 1 [bar] *)
    rMeltPressure_CH2       : REAL;     (* Die head melt pressure transducer Channel 2 [bar] *)
    rMeltPressure_CH3       : REAL;     (* Die head melt pressure transducer Channel 3 [bar] *)
    rBarrelTemp_Zone8       : REAL;     (* Pre-die barrel metering zone temperature [deg C] *)
    rDieAdapterTemp         : REAL;     (* Extrusion die plate and nozzle body surface temperature [deg C] *)
    rScrewSpeed_Actual      : REAL;     (* Co-rotating twin-screw drive shaft velocity feedback [rpm] *)
    rMotorTorque_Actual     : REAL;     (* Extruder drive motor shaft measured torque [Nm] *)
    rPolymerFeedRate_Actual : REAL;     (* Primary gravimetric loss-in-weight feeder mass flow rate [kg/h] *)
    rAPIFeedRate_Actual     : REAL;     (* Micro-gravimetric feeder API mass flow rate [kg/h] *)
    rCoolingBathTemp_Actual : REAL;     (* Strand quench bath circulating fluid temperature [deg C] *)
    rStrandTension_Actual   : REAL;     (* Downstream haul-off haulage strand tension load [N] *)
    rMeltPressure_Setpoint  : REAL;     (* Target die entrance melt pressure setpoint [bar] *)
    rDieTemp_Setpoint       : REAL;     (* Target die zone thermal setpoint [deg C] *)
    rCoolingBathTemp_Setpoint: REAL;    (* Target quench bath temperature setpoint [deg C] *)
    rCycleTime_Sec          : REAL := 0.050; (* Discrete PLC cyclic task execution interval [s] *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Critical process parameters within validated design space *)
    bProcessInSpec          : BOOL;     (* cGMP Quality by Design (QbD) in-spec flag for Critical Quality Attributes *)
    rScrewSpeed_Demand      : REAL;     (* Dynamic twin-screw motor speed velocity command [rpm] *)
    rFeederSpeed_Demand     : REAL;     (* Master gravimetric polymer feeder setpoint command [kg/h] *)
    rAPIFeeder_Demand       : REAL;     (* Secondary micro-feeder active pharmaceutical ingredient setpoint [kg/h] *)
    rDieHeater_PWM          : REAL;     (* Die adapter electric band heater solid-state relay PWM duty [0.0 - 100.0 %] *)
    rCoolingValve_Demand    : REAL;     (* Strand cooling bath chilled heat exchanger valve demand [0.0 - 100.0 %] *)
    rHaulOffSpeed_Demand    : REAL;     (* Downstream strand puller / conveyor linear velocity demand [m/min] *)
    rVotedMeltPressure      : REAL;     (* Validated 2oo3 TMR median voted die melt pressure [bar] *)
    rSpecificMechEnergy     : REAL;     (* Real-time calculated Specific Mechanical Energy (SME) [kJ/kg] *)
    rTotalThroughput_Calc   : REAL;     (* Instantaneous combined mass flow rate [kg/h] *)
    wExtruderStatusWord     : WORD;     (* Packed machine status bitfield (16-bit) *)
    dwAlarmWord             : DWORD;    (* ISA-18.2 compliant fault & event register (32-bit) *)
    iCurrentState           : INT;      (* Active operational state index in finite state machine *)
END_VAR
VAR
    (* --- 2oo3 Triple Modular Redundancy (TMR) Melt Pressure Variables --- *)
    bCH1_Healthy            : BOOL;     (* Channel 1 transducer signal health flag *)
    bCH2_Healthy            : BOOL;     (* Channel 2 transducer signal health flag *)
    bCH3_Healthy            : BOOL;     (* Channel 3 transducer signal health flag *)
    iHealthySensorCount     : INT;      (* Count of operational melt pressure transducers (0..3) *)
    rDelta_12               : REAL;     (* Absolute pressure discrepancy |CH1 - CH2| [bar] *)
    rDelta_23               : REAL;     (* Absolute pressure discrepancy |CH2 - CH3| [bar] *)
    rDelta_31               : REAL;     (* Absolute pressure discrepancy |CH3 - CH1| [bar] *)
    rMaxAllowedDiscrepancy  : REAL := 7.5;   (* Maximum allowed inter-transducer deviation [bar] *)
    rSensorLowThreshold     : REAL := 0.2;   (* Disconnect / open-loop transducer detection limit [bar] *)
    rSensorHighThreshold    : REAL := 340.0; (* Transducer over-range saturation limit [bar] *)
    rP_TareOffset1          : REAL := 0.0;   (* CH1 atmospheric zero calibration offset [bar] *)
    rP_TareOffset2          : REAL := 0.0;   (* CH2 atmospheric zero calibration offset [bar] *)
    rP_TareOffset3          : REAL := 0.0;   (* CH3 atmospheric zero calibration offset [bar] *)
    rP_Corrected1           : REAL;     (* Tare-corrected CH1 pressure [bar] *)
    rP_Corrected2           : REAL;     (* Tare-corrected CH2 pressure [bar] *)
    rP_Corrected3           : REAL;     (* Tare-corrected CH3 pressure [bar] *)

    (* --- PT1 First-Order Lag Filter States --- *)
    rFilter_P_Melt          : REAL := 0.0; (* Filtered voted melt pressure accumulator [bar] *)
    rFilter_DieTemp         : REAL := 25.0; (* Filtered die temperature accumulator [deg C] *)
    rFilter_Torque          : REAL := 0.0; (* Filtered drive motor shaft torque [Nm] *)
    rFilter_Tension         : REAL := 0.0; (* Filtered strand tension accumulator [N] *)
    rAlpha_Fast             : REAL := 0.15; (* Smoothing constant for dynamic pressure feedback *)
    rAlpha_Slow             : REAL := 0.05; (* Smoothing constant for thermal feedback *)

    (* --- 2x2 MIMO Discrete State-Space Model & Predictive Observer --- *)
    (* State Vector x = [x1; x2] = [Backpressure Resistance (bar); Die Thermal Mass (deg C)] *)
    (* Input Vector u = [u1; u2] = [Delta Screw Speed (rpm); Delta Heater Duty (%)] *)
    rState_x1               : REAL := 0.0;
    rState_x2               : REAL := 25.0;
    rState_x1_Next          : REAL;
    rState_x2_Next          : REAL;
    rObs_e1                 : REAL;     (* Innovation error on melt pressure [bar] *)
    rObs_e2                 : REAL;     (* Innovation error on die temperature [deg C] *)

    (* State-Space Plant Matrices (Linearized at 150 rpm, 120 bar, 175 deg C) *)
    rA11                    : REAL := 0.9420;
    rA12                    : REAL := -0.0315;
    rA21                    : REAL := 0.0042;
    rA22                    : REAL := 0.9880;

    rB11                    : REAL := 0.4250;  (* Sensitivity of dP/dt to Screw Speed [bar/rpm] *)
    rB12                    : REAL := -0.1120; (* Sensitivity of dP/dt to Die Heating (melt thinning) [bar/%] *)
    rB21                    : REAL := 0.0085;  (* Viscous dissipation heating from screw shear [deg C/rpm] *)
    rB22                    : REAL := 0.1850;  (* Electric band heater thermal injection [deg C/%] *)

    (* Observer Gain Matrix L (Steady-State Discrete Kalman Filter Gain) *)
    rL11                    : REAL := 0.3200;
    rL12                    : REAL := -0.0150;
    rL21                    : REAL := 0.0080;
    rL22                    : REAL := 0.2450;

    (* Model Predictive Controller Gains (Unconstrained QP Horizon Solution with Slew Limits) *)
    rKmpc_P_Speed           : REAL := 0.850;   (* Screw speed correction gain per bar pressure error *)
    rKmpc_P_Heat            : REAL := -0.220;  (* Die heater correction gain per bar pressure error *)
    rKmpc_T_Speed           : REAL := -0.040;  (* Screw speed trimming gain per deg C thermal error *)
    rKmpc_T_Heat            : REAL := 1.450;   (* Die heater gain per deg C thermal error *)

    (* Controller Internal Drives and Integrators *)
    rSpeed_Command_Raw      : REAL := 0.0;
    rHeater_Command_Raw     : REAL := 0.0;
    rBathValve_Integrator   : REAL := 0.0;
    rPullerSpeed_Command_Raw: REAL := 0.0;
    rTension_Integrator     : REAL := 0.0;

    (* --- Finite State Machine Execution Management --- *)
    iState                  : INT := 0; (* Internal execution state *)
    tStateTimer             : TON;      (* Multi-purpose state dwell timer *)
    tPurgeTimer             : TON;      (* Purge cycle duration timer *)
    tDiscrepancyTimer       : TON;      (* Transducer divergence debounce timer *)
    bStateInitialized       : BOOL := FALSE;

    (* --- Quality & Operating Boundary Constants (GAMP 5 QbD Design Space) --- *)
    rP_Overpressure_Trip    : REAL := 285.0; (* Mechanical rupture disc safety margin [bar] *)
    rP_Overpressure_Warn    : REAL := 245.0; (* Upper operational boundary warning [bar] *)
    rP_Underpressure_Warn   : REAL := 25.0;  (* Loss of die fill / surge cavitation limit [bar] *)
    rTorque_Max_Trip        : REAL := 195.0; (* Extruder gearbox shear pin electronic limit [Nm] *)
    rTorque_Warn            : REAL := 160.0; (* High mechanical torque warning [Nm] *)
    rDieTemp_Tol_High       : REAL := 15.0;  (* Maximum thermal excursion before API degradation [deg C] *)
    rDieTemp_Tol_Low        : REAL := -12.0; (* Cold die freezing / nozzle crystallization risk [deg C] *)
    rSME_Max_Degradation    : REAL := 450.0; (* Threshold for molecular chain scission & API cleavage [kJ/kg] *)
    rSME_Min_IncompleteMelt : REAL := 80.0;  (* Lower boundary for complete crystalline amorphization [kJ/kg] *)

    (* --- Mathematical Auxiliary Temporaries --- *)
    rPower_kW               : REAL;
    rTotalMassFlow_kgh      : REAL;
    rTargetHaulRatio        : REAL := 1.82;  (* Strand draw-down ratio constant [m/(min * kg/h)] *)
    rP_Error                : REAL;
    rT_Error                : REAL;
    rBathTemp_Error         : REAL;
    rTension_Error          : REAL;
    rDeltaU1                : REAL;
    rDeltaU2                : REAL;
END_VAR

(* === 1. SAFETY INTERLOCK & HARDWARE CIRCUIT SUPERVISION === *)
IF NOT bEmergencyStop THEN
    bSystemReady            := FALSE;
    bProcessInSpec          := FALSE;
    rScrewSpeed_Demand      := 0.0;
    rFeederSpeed_Demand     := 0.0;
    rAPIFeeder_Demand       := 0.0;
    rDieHeater_PWM          := 0.0;
    rCoolingValve_Demand    := 100.0; (* Full quench safety mode *)
    rHaulOffSpeed_Demand    := 0.0;
    wExtruderStatusWord     := 16#0000;
    dwAlarmWord             := dwAlarmWord OR 16#00000001; (* Safety Circuit Tripped *)
    iState                  := 0;
    iCurrentState           := 0;
    RETURN;
ELSE
    dwAlarmWord             := dwAlarmWord AND NOT 16#00000001;
END_IF;

(* === 2. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) PRESSURE VOTING ALGORITHM === *)
(* Apply zero tare corrections established during calibration sequence *)
rP_Corrected1 := rMeltPressure_CH1 - rP_TareOffset1;
rP_Corrected2 := rMeltPressure_CH2 - rP_TareOffset2;
rP_Corrected3 := rMeltPressure_CH3 - rP_TareOffset3;

(* Validate raw electrical signal validity boundaries *)
bCH1_Healthy := (rP_Corrected1 >= rSensorLowThreshold) AND (rP_Corrected1 <= rSensorHighThreshold);
bCH2_Healthy := (rP_Corrected2 >= rSensorLowThreshold) AND (rP_Corrected2 <= rSensorHighThreshold);
bCH3_Healthy := (rP_Corrected3 >= rSensorLowThreshold) AND (rP_Corrected3 <= rSensorHighThreshold);

(* Compute pairwise absolute discrepancy matrix *)
rDelta_12 := ABS(rP_Corrected1 - rP_Corrected2);
rDelta_23 := ABS(rP_Corrected2 - rP_Corrected3);
rDelta_31 := ABS(rP_Corrected3 - rP_Corrected1);

(* Dynamic channel isolation if individual sensor drifts beyond fault tolerance *)
IF bCH1_Healthy AND bCH2_Healthy AND bCH3_Healthy THEN
    IF (rDelta_12 > rMaxAllowedDiscrepancy) AND (rDelta_31 > rMaxAllowedDiscrepancy) THEN
        bCH1_Healthy := FALSE; (* Transducer 1 identified as rogue outlier *)
    ELSIF (rDelta_12 > rMaxAllowedDiscrepancy) AND (rDelta_23 > rMaxAllowedDiscrepancy) THEN
        bCH2_Healthy := FALSE; (* Transducer 2 identified as rogue outlier *)
    ELSIF (rDelta_23 > rMaxAllowedDiscrepancy) AND (rDelta_31 > rMaxAllowedDiscrepancy) THEN
        bCH3_Healthy := FALSE; (* Transducer 3 identified as rogue outlier *)
    END_IF;
END_IF;

iHealthySensorCount := BOOL_TO_INT(bCH1_Healthy) + BOOL_TO_INT(bCH2_Healthy) + BOOL_TO_INT(bCH3_Healthy);

(* Fault tolerant voting resolution *)
CASE iHealthySensorCount OF
    3: (* True 2oo3 TMR Median Selection *)
        IF ((rP_Corrected1 >= rP_Corrected2) AND (rP_Corrected1 <= rP_Corrected3)) OR
           ((rP_Corrected1 >= rP_Corrected3) AND (rP_Corrected1 <= rP_Corrected2)) THEN
            rVotedMeltPressure := rP_Corrected1;
        ELSIF ((rP_Corrected2 >= rP_Corrected1) AND (rP_Corrected2 <= rP_Corrected3)) OR
              ((rP_Corrected2 >= rP_Corrected3) AND (rP_Corrected2 <= rP_Corrected1)) THEN
            rVotedMeltPressure := rP_Corrected2;
        ELSE
            rVotedMeltPressure := rP_Corrected3;
        END_IF;
        dwAlarmWord := dwAlarmWord AND NOT 16#0000000E;

    2: (* Graceful Degradation to 1oo2 Dual Redundant Averaging *)
        IF bCH1_Healthy AND bCH2_Healthy THEN
            rVotedMeltPressure := (rP_Corrected1 + rP_Corrected2) * 0.5;
        ELSIF bCH2_Healthy AND bCH3_Healthy THEN
            rVotedMeltPressure := (rP_Corrected2 + rP_Corrected3) * 0.5;
        ELSE
            rVotedMeltPressure := (rP_Corrected1 + rP_Corrected3) * 0.5;
        END_IF;
        dwAlarmWord := (dwAlarmWord OR 16#00000002) AND NOT 16#0000000C; (* Warning: 2oo3 Degraded to 1oo2 *)

    1: (* Failover to Single Channel Mode with Process Warning *)
        IF bCH1_Healthy THEN
            rVotedMeltPressure := rP_Corrected1;
        ELSIF bCH2_Healthy THEN
            rVotedMeltPressure := rP_Corrected2;
        ELSE
            rVotedMeltPressure := rP_Corrected3;
        END_IF;
        dwAlarmWord := (dwAlarmWord OR 16#00000004) AND NOT 16#00000008; (* Critical: Simplex Operation *)

    ELSE
        (* Total Loss of Redundancy - Immediate Safety Abort *)
        dwAlarmWord := dwAlarmWord OR 16#00000008; (* Severe Alarm: All Pressure Sensors Lost *)
        iState := 99; (* Transition directly to emergency shutdown *)
END_CASE;

(* === 3. DIGITAL SIGNAL CONDITIONING (FIRST-ORDER PT1 LOW PASS) === *)
rFilter_P_Melt  := rFilter_P_Melt  + rAlpha_Fast * (rVotedMeltPressure       - rFilter_P_Melt);
rFilter_DieTemp := rFilter_DieTemp + rAlpha_Slow * (rDieAdapterTemp          - rFilter_DieTemp);
rFilter_Torque  := rFilter_Torque  + rAlpha_Fast * (rMotorTorque_Actual      - rFilter_Torque);
rFilter_Tension := rFilter_Tension + rAlpha_Fast * (rStrandTension_Actual    - rFilter_Tension);

(* === 4. CONTINUOUS RHEOLOGICAL & PROCESS ANALYTICAL TECHNOLOGY (PAT) METRICS === *)
rTotalMassFlow_kgh := rPolymerFeedRate_Actual + rAPIFeedRate_Actual;
rTotalThroughput_Calc := rTotalMassFlow_kgh;

(* Mechanical shaft power: P [kW] = (2 * pi * N [rpm] * Torque [Nm]) / 60000 *)
rPower_kW := (6.2831853 * rScrewSpeed_Actual * rFilter_Torque) / 60000.0;

(* Specific Mechanical Energy: SME [kJ/kg] = (P [kW] * 3600 [s/h]) / MassFlow [kg/h] *)
IF rTotalMassFlow_kgh > 0.05 THEN
    rSpecificMechEnergy := (rPower_kW * 3600.0) / rTotalMassFlow_kgh;
ELSE
    rSpecificMechEnergy := 0.0;
END_IF;

(* === 5. 2x2 MIMO MODEL PREDICTIVE CONTROL & STATE OBSERVER CORE === *)
(* State Observer Update: Innovation error injection *)
rObs_e1 := rFilter_P_Melt  - rState_x1;
rObs_e2 := rFilter_DieTemp - rState_x2;

rState_x1 := rState_x1 + (rL11 * rObs_e1 + rL12 * rObs_e2);
rState_x2 := rState_x2 + (rL21 * rObs_e1 + rL22 * rObs_e2);

(* Discrete System State Propagation: x(k+1) = A*x(k) + B*u(k) *)
rDeltaU1 := rScrewSpeed_Demand - 150.0;   (* Shifted around nominal operating point 150 rpm *)
rDeltaU2 := rDieHeater_PWM     - 45.0;    (* Shifted around nominal operating point 45% PWM *)

rState_x1_Next := (rA11 * rState_x1 + rA12 * rState_x2) + (rB11 * rDeltaU1 + rB12 * rDeltaU2);
rState_x2_Next := (rA21 * rState_x1 + rA22 * rState_x2) + (rB21 * rDeltaU1 + rB22 * rDeltaU2);

(* Overwrite state for subsequent scan step *)
rState_x1 := rState_x1_Next;
rState_x2 := rState_x2_Next;

(* Compute Error Vectors against setpoint trajectory *)
rP_Error := rMeltPressure_Setpoint - rState_x1;
rT_Error := rDieTemp_Setpoint      - rState_x2;

(* Analytical MPC Control Inversion with Viscous Cross-Coupling Compensation *)
rSpeed_Command_Raw  := 150.0 + (rKmpc_P_Speed * rP_Error) + (rKmpc_T_Speed * rT_Error);
rHeater_Command_Raw := 45.0  + (rKmpc_P_Heat  * rP_Error) + (rKmpc_T_Heat  * rT_Error);

(* === 6. DOWNSTREAM STRAND COOLING & HAUL-OFF KINEMATICS REGULATION === *)
(* Chilled quench bath PID thermal tracking *)
rBathTemp_Error := rCoolingBathTemp_Actual - rCoolingBathTemp_Setpoint;
rBathValve_Integrator := rBathValve_Integrator + (0.05 * rBathTemp_Error * rCycleTime_Sec);

(* Anti-windup saturation limits on cooling integrator *)
IF rBathValve_Integrator > 100.0 THEN
    rBathValve_Integrator := 100.0;
ELSIF rBathValve_Integrator < 0.0 THEN
    rBathValve_Integrator := 0.0;
END_IF;

rCoolingValve_Demand := (3.2 * rBathTemp_Error) + rBathValve_Integrator;
IF rCoolingValve_Demand > 100.0 THEN
    rCoolingValve_Demand := 100.0;
ELSIF rCoolingValve_Demand < 0.0 THEN
    rCoolingValve_Demand := 0.0;
END_IF;

(* Haul-off linear speed synchronized to volumetric die throughput with strand tension trim *)
rPullerSpeed_Command_Raw := rTotalMassFlow_kgh * rTargetHaulRatio * 0.085;
rTension_Error := rFilter_Tension - 14.5; (* 14.5 N target strand solidification tension *)
rTension_Integrator := rTension_Integrator + (0.012 * rTension_Error * rCycleTime_Sec);

IF rTension_Integrator > 2.0 THEN
    rTension_Integrator := 2.0;
ELSIF rTension_Integrator < -2.0 THEN
    rTension_Integrator := -2.0;
END_IF;

rHaulOffSpeed_Demand := rPullerSpeed_Command_Raw + (0.035 * rTension_Error) + rTension_Integrator;
IF rHaulOffSpeed_Demand < 0.0 THEN
    rHaulOffSpeed_Demand := 0.0;
ELSIF rHaulOffSpeed_Demand > 25.0 THEN
    rHaulOffSpeed_Demand := 25.0;
END_IF;

(* === 7. MULTI-STAGE FINITE STATE MACHINE (FSM) INDUSTRIAL LOGIC === *)
CASE iState OF
    0: (* STATE_IDLE_SAFE_OFF: Complete system stand-down *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 0.0;
        rFeederSpeed_Demand     := 0.0;
        rAPIFeeder_Demand       := 0.0;
        rDieHeater_PWM          := 0.0;
        rHaulOffSpeed_Demand    := 0.0;
        tStateTimer(IN := FALSE);

        IF bEnable THEN
            iState := 10; (* Proceed to thermal preheat *)
        END_IF;

    10: (* STATE_THERMAL_SOAK_PREHEAT: Barrel & die body thermal expansion and soak *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 0.0;
        rFeederSpeed_Demand     := 0.0;
        rAPIFeeder_Demand       := 0.0;
        rDieHeater_PWM          := 75.0; (* Pre-heat duty cycle *)

        (* Verify die temperature has entered +/- 3.0 deg C tolerance window *)
        IF (ABS(rFilter_DieTemp - rDieTemp_Setpoint) <= 3.0) AND 
           (rBarrelTemp_Zone8 >= (rDieTemp_Setpoint - 5.0)) THEN
            tStateTimer(IN := TRUE, PT := T#45S); (* Soak dwell time *)
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iState := 20; (* Transition to TMR transducer zero calibration *)
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

    20: (* STATE_TMR_PRESSURE_ZERO_TARE: Calibrate ambient atmospheric offset *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 0.0;

        (* Capture atmospheric pressure tare offsets *)
        rP_TareOffset1 := rMeltPressure_CH1;
        rP_TareOffset2 := rMeltPressure_CH2;
        rP_TareOffset3 := rMeltPressure_CH3;

        tStateTimer(IN := TRUE, PT := T#2S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 30; (* Advance to mechanical dry rotation check *)
        END_IF;

    30: (* STATE_SCREW_DRY_ROTATION_TEST: Low-speed mechanical friction assessment *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 15.0; (* Low speed jog [rpm] *)
        rFeederSpeed_Demand     := 0.0;
        rAPIFeeder_Demand       := 0.0;

        tStateTimer(IN := TRUE, PT := T#10S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            (* Verify screw motor torque is below unlubricated mechanical binding threshold *)
            IF rFilter_Torque < 35.0 THEN
                iState := 40; (* Advance to polymer prime fill *)
            ELSE
                dwAlarmWord := dwAlarmWord OR 16#00000040; (* Mechanical Binding Fault *)
                iState := 99; (* Trip into safety lockout *)
            END_IF;
        END_IF;

    40: (* STATE_POLYMER_PRIME_FILL: Initial polymer matrix melt pool creation *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 60.0;  (* Prime speed [rpm] *)
        rFeederSpeed_Demand     := 1.8;   (* Polymer prime flow [kg/h] *)
        rAPIFeeder_Demand       := 0.0;   (* API withheld *)
        rDieHeater_PWM          := 55.0;

        (* Wait for die head backpressure build-up confirming screw flight filling *)
        IF rFilter_P_Melt >= 35.0 THEN
            tStateTimer(IN := TRUE, PT := T#15S);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iState := 50; (* Advance to API dosing ramp *)
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

    50: (* STATE_API_RAMP_AND_STABILIZE: Introduce active pharmaceutical compound *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 120.0;
        rFeederSpeed_Demand     := 3.6;   (* Polymer base [kg/h] *)
        rAPIFeeder_Demand       := 0.9;   (* API at 20% total drug loading [kg/h] *)
        rDieHeater_PWM          := rHeater_Command_Raw;

        tStateTimer(IN := TRUE, PT := T#30S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 60; (* Transition to full cGMP closed-loop production *)
        END_IF;

    60: (* STATE_STEADY_STATE_QBD_PRODUCTION: Closed-loop MPC melt profiling *)
        bSystemReady            := TRUE;

        (* Apply bounded outputs from MIMO Model Predictive Controller *)
        IF rSpeed_Command_Raw > 280.0 THEN
            rScrewSpeed_Demand := 280.0;
        ELSIF rSpeed_Command_Raw < 50.0 THEN
            rScrewSpeed_Demand := 50.0;
        ELSE
            rScrewSpeed_Demand := rSpeed_Command_Raw;
        END_IF;

        IF rHeater_Command_Raw > 95.0 THEN
            rDieHeater_PWM := 95.0;
        ELSIF rHeater_Command_Raw < 5.0 THEN
            rDieHeater_PWM := 5.0;
        ELSE
            rDieHeater_PWM := rHeater_Command_Raw;
        END_IF;

        rFeederSpeed_Demand := 4.0;
        rAPIFeeder_Demand   := 1.0;

        (* Check operator purge request *)
        IF bPurgeRequest THEN
            iState := 70;
        END_IF;

        (* Check enable dropped *)
        IF NOT bEnable THEN
            iState := 80;
        END_IF;

    70: (* STATE_PURGE_AND_FLUSH: High-shear purging of thermal-sensitive drug API *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rAPIFeeder_Demand       := 0.0;   (* Instantly stop drug substance dosing *)
        rFeederSpeed_Demand     := 6.5;   (* Maximum polymer flush rate [kg/h] *)
        rScrewSpeed_Demand      := 220.0; (* High shear flush velocity [rpm] *)
        rDieHeater_PWM          := 60.0;

        tPurgeTimer(IN := TRUE, PT := T#90S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 80; (* Transition to controlled cooling *)
        END_IF;

    80: (* STATE_CONTROLLED_COOLING_SHUTDOWN: Ramp down line and prevent freeze-up *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rFeederSpeed_Demand     := 0.0;
        rAPIFeeder_Demand       := 0.0;
        rDieHeater_PWM          := 0.0;

        (* Low rotation speed to evacuate remaining melt prior to barrel freeze *)
        IF rFilter_P_Melt > 5.0 THEN
            rScrewSpeed_Demand := 25.0;
        ELSE
            rScrewSpeed_Demand := 0.0;
        END_IF;

        tStateTimer(IN := TRUE, PT := T#60S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            rScrewSpeed_Demand := 0.0;
            iState := 0; (* Return to safe off *)
        END_IF;

    99: (* STATE_FAULT_LOCKOUT_TRIP: Emergency graceful degradation lock *)
        bSystemReady            := FALSE;
        bProcessInSpec          := FALSE;
        rScrewSpeed_Demand      := 0.0;
        rFeederSpeed_Demand     := 0.0;
        rAPIFeeder_Demand       := 0.0;
        rDieHeater_PWM          := 0.0;
        rHaulOffSpeed_Demand    := 0.0;
        rCoolingValve_Demand    := 100.0; (* Quench all hot melt strands *)

        IF NOT bEnable THEN
            iState := 0; (* Reset only after master enable toggled off *)
        END_IF;

    ELSE
        iState := 0;
END_CASE;

(* Update current state export *)
iCurrentState := iState;

(* === 8. CRITICAL PROCESS PARAMETER (CPP) & QUALITY BY DESIGN (QBD) ASSESSMENT === *)
