   (ABS(rFilter_P_Melt  - rMeltPressure_Setpoint) <= 12.0) AND 
   (ABS(rFilter_DieTemp - rDieTemp_Setpoint)      <= 2.5)  AND 
   (rSpecificMechEnergy >= rSME_Min_IncompleteMelt)       AND 
   (rSpecificMechEnergy <= rSME_Max_Degradation)          AND 
   (iHealthySensorCount >= 2)                             THEN
