    dwAlarmWord := dwAlarmWord OR 16#00000200; (* Die Thermal Runaway / API Degradation Risk *)
ELSIF (rFilter_DieTemp - rDieTemp_Setpoint) < rDieTemp_Tol_Low THEN
    dwAlarmWord := dwAlarmWord OR 16#00000400; (* Die Cold Plug / Crystallization Risk *)
ELSE
