(* === 10. PACKED STATUS BITFIELD ENCODING === *)
wExtruderStatusWord.0 := bSystemReady;
wExtruderStatusWord.1 := bProcessInSpec;
wExtruderStatusWord.2 := (iState = 60);         (* Production active *)
wExtruderStatusWord.3 := (iHealthySensorCount = 3); (* 2oo3 Full Health *)
wExtruderStatusWord.4 := (iHealthySensorCount = 2); (* 2oo3 Degraded *)
